import styled from '@emotion/styled';

interface StyledCountrySlideContainerProps {
  $hasAlert?: boolean;
}

export const StyledCountrySlideContainer = styled('div', {
  shouldForwardProp: (propName) => propName !== '$hasAlert',
})<StyledCountrySlideContainerProps>(({ $hasAlert = false }) => ({
  display: 'grid',
  gridTemplateColumns: 'repeat(3, 1fr)',
  gap: '16px',
  alignItems: 'start',

  ...($hasAlert === false && {
    gridTemplateAreas: `
          "total brands brands"
        `,
  }),

  ...($hasAlert === true && {
    gridTemplateAreas: `
          "alert alert alert"
          "total brands brands"
        `,
  }),
}));
